        f = factor.loc[d]
        r = fwd_ret.loc[d]
        pair = pd.concat([f.rename("f"), r.rename("r")], axis=1).dropna()
        if len(pair) < min_valid:
            continue
        if pair["f"].nunique() < 3 or pair["r"].nunique() < 2:
